#include <bits/stdc++.h>
using namespace std;

const int MAXN = 300;
const int ROOM = -1;
const int REAC = -2;
const int BAD_REAC = -3;
const int CAPSULE = ROOM;

int station[MAXN][MAXN], capsuleAt[MAXN][MAXN];
int poison[61][MAXN][MAXN];
int dx[4] = {-1, 0, 1, 0};
int dy[4] = {0, -1, 0, 1};

struct Pos {
    int x, y, qnt;
    Pos(int _x = 0, int _y = 0, int _q = 0) : x(_x), y(_y), qnt(_q) {}
};

vector<Pos> person, capsule;

bool inside(int x, int y, int n) {
    return x >= 0 && x < n && y >= 0 && y < n && station[x][y] == ROOM;
}

int cellType(char c) {
    if (c >= '0' && c <= '9') return ROOM;
    if (c == 'Y') return REAC;
    if (c == 'Z') return BAD_REAC;
    return -1;
}

int cellNumber(char c) {
    return c - '0';
}

void spread_venom(int x, int y, int T, int n) {
    poison[0][x][y] = 1;
    for (int t = 1; t <= T; ++t) {
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (poison[t - 1][i][j]) {
                    poison[t][i][j] = 1;
                    for (int d = 0; d < 4; ++d) {
                        int ni = i + dx[d], nj = j + dy[d];
                        if (inside(ni, nj, n)) poison[t][ni][nj] = 1;
                    }
                }
            }
        }
    }
}

int travel_time(const Pos &a, const Pos &b, int n, int T) {
    vector<bitset<MAXN>> seen(n);
    queue<pair<int, Pos>> q;
    q.push({0, a});
    seen[a.x][a.y] = 1;

    while (!q.empty()) {
        int t = q.front().first;
        Pos cur = q.front().second;
        q.pop();

        if (cur.x == b.x && cur.y == b.y) return t;
        if (t == T) continue;
        if (poison[t][cur.x][cur.y]) continue;

        for (int d = 0; d < 4; ++d) {
            Pos nxt(cur.x + dx[d], cur.y + dy[d], 0);
            if (inside(nxt.x, nxt.y, n) && !seen[nxt.x][nxt.y] && !poison[t][nxt.x][nxt.y]) {
                seen[nxt.x][nxt.y] = 1;
                q.push({t + 1, nxt});
            }
        }
    }
    return 999;
}

struct Edge {
    int to, rev, flow, cap;
    int rest() const {
        return cap - flow;
    }
};

class FlowNetwork {
    int n;
    vector<vector<Edge>> adj;
    vector<int> parent, parentEdge;

public:
    FlowNetwork(int _n) : n(_n), adj(_n), parent(_n), parentEdge(_n) {}

    void addEdge(int u, int v, int c) {
        Edge a = {v, (int)adj[v].size(), 0, c};
        Edge b = {u, (int)adj[u].size(), 0, 0};
        adj[u].push_back(a);
        adj[v].push_back(b);
    }

    bool bfs(int s, int t) {
        fill(parent.begin(), parent.end(), -1);
        fill(parentEdge.begin(), parentEdge.end(), -1);

        queue<int> q;
        q.push(s);
        parent[s] = s;

        while (!q.empty()) {
            int u = q.front();
            q.pop();

            for (int i = 0; i < (int)adj[u].size(); ++i) {
                Edge &e = adj[u][i];
                if (e.rest() > 0 && parent[e.to] == -1) {
                    parent[e.to] = u;
                    parentEdge[e.to] = i;
                    if (e.to == t) return true;
                    q.push(e.to);
                }
            }
        }
        return false;
    }

    int augment(int s, int t) {
        int pushed = INT_MAX;
        for (int v = t; v != s; v = parent[v]) {
            pushed = min(pushed, adj[parent[v]][parentEdge[v]].rest());
        }

        for (int v = t; v != s; v = parent[v]) {
            Edge &e = adj[parent[v]][parentEdge[v]];
            e.flow += pushed;
            adj[v][e.rev].flow -= pushed;
        }

        return pushed;
    }

    long long maxFlow(int s, int t) {
        int total = 0;
        while (bfs(s, t)) total += augment(s, t);
        return total;
    }
};

int main() {
    int N, T;
    scanf(" %d %d", &N, &T);

    Pos bad(0, 0, 0);
    char ch;

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            scanf(" %c", &ch);
            int type = cellType(ch);
            int value = cellNumber(ch);

            station[i][j] = type;
            if (type == ROOM && value > 0) person.push_back(Pos(i, j, value));
            if (type == BAD_REAC) bad = Pos(i, j, 0);
        }
    }

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            scanf(" %c", &ch);
            int type = cellType(ch);
            int value = cellNumber(ch);

            if (type == CAPSULE && value > 0) {
                capsule.push_back(Pos(i, j, value));
                capsuleAt[i][j] = value;
            }
        }
    }

    FlowNetwork flow(MAXN);
    int S = 0, SNK = MAXN - 1;

    for (size_t i = 0; i < person.size(); ++i)
        flow.addEdge(S, (int)i * 2 + 1, person[i].qnt);

    for (size_t i = 0; i < capsule.size(); ++i)
        flow.addEdge((int)i * 2 + 2, SNK, capsule[i].qnt);

    spread_venom(bad.x, bad.y, T, N);

    for (size_t i = 0; i < person.size(); ++i) {
        for (size_t j = 0; j < capsule.size(); ++j) {
            int t = travel_time(person[i], capsule[j], N, T);
            if (t <= T) flow.addEdge((int)i * 2 + 1, (int)j * 2 + 2, 999);
        }
    }

    printf("%lld\n", flow.maxFlow(S, SNK));
    return 0;
}
